// Generated by the icon-variant sheet run: swaps the spend button's
// icon so one candidate per capture can be compared side by side.
(() => {
  const button = document.querySelector('[aria-label="Token 用量与金额"]');
  const svg = button && button.querySelector('svg');
  if (!svg) throw new Error('spend button icon not found');
  svg.innerHTML = '<path d="M21 12c.552 0 1.005-.449.95-.998a10 10 0 0 0-8.953-8.951c-.55-.055-.998.398-.998.95v8a1 1 0 0 0 1 1z"/><path d="M21.21 15.89A10 10 0 1 1 8 2.83"/>';
  return 'chart-pie';
})();
